# ── bookkeeping kit: shared helpers (inlined into each node by gen-ext.js) ──
import json
import re
import datetime
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"
BK_REQUESTS = "Bookkeeping Requests"


def bk_slug(name):
    s = re.sub(r"[^a-z0-9]+", "-", str(name or "").lower()).strip("-")
    return s[:40].strip("-") or "client"


def bk_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def bk_write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def bk_money(value):
    """Parse 1234.5, "1,234.50", "$12" or "A$ 12.00" into a float; None when blank or not a number."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = re.sub(r"[^0-9.\-]", "", str(value))
    if s in ("", "-", ".", "-."):
        return None
    try:
        return float(s)
    except ValueError:
        return None


def bk_fmt(amount, currency=""):
    if amount is None:
        return "—"
    return (currency + " " if currency else "") + "{:,.2f}".format(amount)


def bk_tz(settings):
    # The sandbox may lack the tz database; fall back to AEST (UTC+10) rather than failing the run.
    try:
        return ZoneInfo((settings or {}).get("timezone") or "Australia/Sydney")
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=10))


def bk_now_iso(settings):
    return datetime.datetime.now(bk_tz(settings)).replace(microsecond=0).isoformat()


def bk_answer(responses, qid):
    """A form answer: str, bool, list, or a lookup {id, label}."""
    return (responses or {}).get(qid)


# ── bookkeeping kit: payroll adapter (inlined into payroll nodes by gen-ext.js) ──
# Xero Payroll AU through xero-payroll-au (reads take xero_tenant_id, so each call lands in the client's own
# organisation) and Deputy through deputy. Read-only: the checks list corrections, the payroll officer makes them.
import csv
import io

from openpyxl import Workbook, load_workbook

BK_PAYROLL = "Bookkeeping/Payroll"
BK_PAYRUNS = "Bookkeeping/PayRuns"
BK_PAYROLL_FILES = "Bookkeeping Payroll"
PAYROLL = "xero-payroll-au"
DEPUTY = "deputy"
PAY_WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
PAY_BANDS = ["ordinary", "early", "late", "saturday", "sunday", "public_holiday", "ot_first", "ot_after"]
PAY_BAND_NAMES = {"ordinary": "ordinary", "early": "early (before start of day)", "late": "late (after end of day)",
                  "saturday": "Saturday", "sunday": "Sunday", "public_holiday": "public holiday",
                  "ot_first": "overtime (first hours)", "ot_after": "overtime (after that)"}


def pay_call(tool, tenant_id=None, **args):
    if tenant_id:
        args["xero_tenant_id"] = tenant_id
    exc = None  # bound first for the platform lint (see xero_call)
    try:
        return api.connectors.invoke(server=PAYROLL, tool=tool, args=args)
    except Exception as exc:
        raise RuntimeError("Xero Payroll: " + str(exc)[:500]) from None


def pay_rows(result, key):
    if isinstance(result, dict):
        rows = result.get(key)
        return rows if isinstance(rows, list) else []
    return result if isinstance(result, list) else []


def pay_date(value):
    """Xero Payroll dates arrive as '/Date(1759276800000+0000)/' or ISO; Deputy's as ISO or epoch seconds."""
    s = str(value or "")
    m = re.match(r"/Date\((-?\d+)", s)
    if m:
        return datetime.datetime.fromtimestamp(int(m.group(1)) / 1000, datetime.timezone.utc).date()
    try:
        return datetime.date.fromisoformat(s[:10])
    except ValueError:
        return None


def pay_name(e):
    return re.sub(r"\s+", " ", (str(e.get("FirstName") or "") + " " + str(e.get("LastName") or "")).strip())


def pay_draft_run(tenant_id, calendar_id, start):
    """The draft pay run for the period with its payslip summaries, or None."""
    where = 'PayrollCalendarID==Guid("%s") AND PayRunStatus=="DRAFT"' % calendar_id
    for r in pay_rows(pay_call("list_pay_runs", tenant_id, where=where), "PayRuns"):
        if pay_date(r.get("PayRunPeriodStartDate")) == start:
            full = pay_rows(pay_call("get_pay_run", tenant_id, payRunId=r["PayRunID"]), "PayRuns")
            return full[0] if full else r
    return None


def pay_run_load(todo_id="", client_name=""):
    """(path, run) for a pay run's WorkQ item (or its review / approval item), or a client's newest open pay run."""
    if todo_id:
        link = bk_read_json(BK_PAYRUNS + "/" + todo_id + ".json") or {}
        if link.get("link"):
            path = BK_PAYRUNS + "/" + link["link"] + ".json"
            return path, bk_read_json(path) or {}
        return "", {}
    if client_name:
        slug = bk_slug(client_name)
        runs = [f for f in api.files.list(path=BK_PAYRUNS)
                if str(f.get("name") or "").startswith(slug + "-") and str(f.get("name") or "").endswith(".json")]
        for f in sorted(runs, key=lambda f: str(f.get("name")), reverse=True):
            run = bk_read_json(f["path"]) or {}
            if run.get("period_start") and run.get("status") not in ("done", "cancelled"):
                return f["path"], run
    return "", {}


def pay_link(todo_id, run):
    """Point a WorkQ item at its pay run record, so its form submissions find the pay run."""
    bk_write_json(BK_PAYRUNS + "/" + todo_id + ".json", {"link": run["slug"] + "-" + run["period_start"]})


# ── Build the review pack ──


import html as _html

todo_id = params.get("todo_id") or ""
responses = params.get("responses") or {}
manual_client = str(params.get("client_name") or "").strip()
answer = str(bk_answer(responses, "q_action") or "").lower()
wanted = answer.startswith("ready") if todo_id else bool(manual_client)
settings = bk_read_json(BK_SETTINGS) or {}
outcome = "ignored"
pack_url = ""


def _esc(v):
    return _html.escape(str(v if v is not None else "—"))


path, run = pay_run_load(todo_id, manual_client) if wanted else ("", {})
if wanted and run:
    ps = bk_read_json(BK_PAYROLL + "/" + run["slug"] + ".json") or {}
    note = str(bk_answer(responses, "q_notes") or "").strip()
    if note:
        run.setdefault("notes", []).append({"at": bk_now_iso(settings), "by": params.get("actor") or "", "text": note[:4000]})
    try:
        draft = pay_draft_run(run["tenant_id"], (run.get("calendar") or {}).get("id") or "",
                              datetime.date.fromisoformat(run["period_start"]))
    except Exception as exc:
        draft = None
        api.workq.comment(todo_id=run["item_id"], body="Couldn't read the draft pay run from Xero Payroll: " + str(exc)[:300])
    if not draft:
        outcome = "no_draft"
        api.workq.comment(todo_id=run["item_id"], body=(
            "There's no draft pay run in Xero Payroll for " + run["period_start"] + " yet. Create it in Xero (Payroll → Pay "
            "employees), then choose **Ready for review** again."))
    else:
        totals = {k: bk_money(draft.get(k)) for k in ("Wages", "Tax", "Super", "Deductions", "Reimbursement", "NetPay")}
        slips = sorted(draft.get("Payslips") or [], key=lambda s: pay_name(s))
        check = run.get("last_check") or {}
        page = ["<!doctype html><html><head><meta charset='utf-8'><title>Pay run review pack</title><style>"
                "body{font-family:system-ui,sans-serif;margin:24px;color:#1f2937}h1{font-size:20px}h2{font-size:16px;margin-top:24px}"
                "table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #e5e7eb;padding:6px 8px;"
                "text-align:left}th{background:#f9fafb}td.n,th.n{text-align:right}.warn{color:#b45309}.muted{color:#6b7280}</style></head><body>",
                "<h1>Pay run review pack: " + _esc(run["name"]) + "</h1>",
                "<p>Pay period " + _esc(run["period_start"]) + " to " + _esc(run["period_end"]) + " · pay day <b>"
                + _esc(run["payment_date"]) + "</b> · " + str(len(slips)) + " employees · prepared by "
                + _esc(ps.get("officer_name") or "the payroll officer") + "</p>",
                "<h2>Totals</h2><table><tr>" + "".join("<th class='n'>" + k + "</th>" for k in
                                                       ("Wages", "Tax", "Super", "Deductions", "Reimbursements", "Net pay")) + "</tr><tr>"
                + "".join("<td class='n'>" + _esc(bk_fmt(totals[k])) + "</td>" for k in
                          ("Wages", "Tax", "Super", "Deductions", "Reimbursement", "NetPay")) + "</tr></table>",
                "<h2>Employees</h2><table><tr><th>Employee</th><th class='n'>Wages</th><th class='n'>Tax</th><th class='n'>Super</th>"
                "<th class='n'>Reimbursements</th><th class='n'>Net pay</th></tr>"]
        for s in slips:
            page.append("<tr><td>" + _esc(pay_name(s)) + "</td>" + "".join(
                "<td class='n'>" + _esc(bk_fmt(bk_money(s.get(k)))) + "</td>" for k in ("Wages", "Tax", "Super", "Reimbursements", "NetPay")) + "</tr>")
        page.append("</table><h2>Checks</h2>")
        if not check:
            page.append("<p class='warn'>The checks weren't run for this pay run.</p>")
        elif check.get("open_items"):
            page.append("<p class='warn'>The last check (" + _esc(check.get("at")) + ") still had " + str(check["open_items"])
                        + " open item(s):</p><ul>" + "".join("<li>" + _esc(x) + "</li>" for x in check.get("summary") or []) + "</ul>")
        else:
            page.append("<p>The last check (" + _esc(check.get("at")) + ") found nothing to fix.</p>")
        if check.get("url"):
            page.append("<p><a href='" + _esc(check["url"]) + "'>Full check report</a></p>")
        if check.get("changes"):
            page.append("<h2>Changes this period</h2><ul>" + "".join("<li>" + _esc(x) + "</li>" for x in check["changes"]) + "</ul>")
        page.append("<h2>Notes</h2>")
        notes = ([{"text": ps["notes"], "at": "settings"}] if ps.get("notes") else []) + (run.get("notes") or [])
        page.append("<ul>" + "".join("<li>" + _esc(n.get("text")) + " <span class='muted'>(" + _esc(n.get("at")) + ")</span></li>"
                                     for n in notes) + "</ul>" if notes else "<p class='muted'>No notes.</p>")
        page.append("</body></html>")
        saved = api.artifacts.put(title=("Pay run review pack: " + run["name"] + " " + run["period_start"])[:200], content="".join(page),
                                  file_name="pay-run-pack-" + run["slug"] + "-" + run["period_start"] + ".html",
                                  description="Pay run review pack")
        pack_url = str((saved or {}).get("url") or "")
        item = api.workq.create(
            title=("Review pay run: " + run["name"] + ", " + run["period_start"] + " to " + run["period_end"])[:200],
            scope="org",
            description=("**" + run["name"] + "**, pay day **" + run["payment_date"] + "**: " + str(len(slips)) + " employees, "
                         "wages " + bk_fmt(totals["Wages"]) + ", net pay " + bk_fmt(totals["NetPay"]) + ".\n\n"
                         + ("The last check still had **" + str(check.get("open_items")) + " open item(s)**.\n\n" if check.get("open_items") else "")
                         + "[Open the review pack](" + pack_url + ")\n\nFill in the **Payroll review** form: approve it for the "
                         "client, or send it back with the changes needed."),
            priority="high",
            due_date=run["payment_date"],
            assignee_ids=[ps["reviewer_id"]] if ps.get("reviewer_id") else None,
            labels=["bookkeeping", "payroll-review", run["slug"]],
        )
        api.workq.attach_form(todo_id=item["id"], form_id=params["review_form"])
        pay_link(item["id"], run)
        run.update(status="in_review", review_item_id=item["id"], pack_url=pack_url, pack_totals=totals, staff=len(slips))
        api.workq.comment(todo_id=run["item_id"], body=("Review pack sent to " + (ps.get("reviewer_name") or "the reviewer")
                                                        + ". [Open the review pack](" + pack_url + ")"))
        outcome = "in_review"
    bk_write_json(path, run)
elif wanted and manual_client:
    outcome = "no_pay_run"
